pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(bytes calldata anyData) public {
        string memory v = c.version();

        assertTrue(keccak256(abi.encodePacked(v)) == keccak256(abi.encodePacked("1.0.0")));
    }
}
